#!/usr/bin/env python3
"""tests/data/lists.txt (dumped display lists 1,3,4,5 of the original) → src/lists.inc."""
import re, sys, os
R = os.path.dirname(os.path.abspath(__file__)) + '/../'
src = open(R + 'tests/data/lists.txt').read().splitlines()
out = ['// Generated by tools/make_lists.py from tests/data/lists.txt (the original display lists,',
       '// dumped from the GL trace with round-trip float precision). Do not edit.', '']
i = 0
while i < len(src):
    _, n, cnt = src[i].split(); n, cnt = int(n), int(cnt); i += 1
    out.append('static void list_%d(GlSink& g) {' % n)
    for c in src[i:i + cnt]:
        name = re.match(r'gl(\w+)\(', c).group(1)
        args = [a.split(' = ')[1] for a in re.findall(r'\w+ = [^,)]+', c)]
        if name in ('Color4f', 'Color3f', 'TexCoord2f', 'Vertex3f'):
            args = [a + ('f' if ('.' in a or 'e' in a) else '.0f') for a in args]
        elif name == 'BlendFunc' or name == 'Begin':
            args = args
        out.append('    g.%s(%s);' % (name, ', '.join(args)))
    out.append('}')
    out.append('')
    i += cnt
open(R + 'src/lists.inc', 'w').write('\n'.join(out))
